pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(0));
        // The bug allows a non-owner to drain funds, so we don't require attacker to be owner.
        // The reference contract would revert for a non-owner before the transfer.
        vm.deal(address(c), amount);
        vm.deal(attacker, 0); // just to ensure attacker is an EOA
        vm.prank(attacker);
        bool ok;
        try c.sendTo(attacker, amount) { ok = true; } catch { ok = false; }
        // Reference: for any non-owner attacker, the call MUST revert (ok == false).
        // Bug: for some non-owner attacker, the call succeeds (ok == true) and funds are stolen.
        // The assertion checks: if the transfer succeeded without revert, the caller must have been the owner.
        // Since we are always calling as 'attacker' who is NOT the owner (we assume attacker != c.owner()),
        // the assertion asserts that ok == false.
        vm.assume(attacker != c.owner());
        assertTrue(!ok);
    }
}

