pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 amount, address receiver) public {
        // Ensure attacker is not the current owner and is not zero
        vm.assume(attacker != address(0));
        vm.assume(attacker != c.owner());
        // Ensure receiver is not zero address, as required by the function logic
        vm.assume(receiver != address(0));
        // Bound amount to avoid revert due to insufficient balance during setup (keep wide)
        vm.assume(amount > 0 && amount <= address(c).balance);

        // Fund the attacker and record the initial contract balance
        vm.deal(attacker, amount);
        uint256 balanceBefore = address(c).balance;

        // Attacker calls sendTo
        vm.prank(attacker);
        try c.sendTo(receiver, amount) {
            // If the call succeeds, it must be a case where the bug allows it.
            // We assert that such a success is impossible for the correct contract, but the bug may succeed.
        } catch {
            // On revert, the contract balance must remain unchanged.
        }

        uint256 balanceAfter = address(c).balance;
        // Property: For a non-owner call that does not revert, the contract balance must not decrease.
        // The correct contract always reverts on non-owner calls, so balanceAfter == balanceBefore holds.
        // The buggy contract may decrease balance (drain) if the transfer succeeds before the owner check reverts.
        // Our assertion is that the balance did not decrease (>= holds if we consider possible revert, but we assert equality because a non-owner call should never succeed).
        // More precisely: a non-owner call either reverts (balance unchanged) or succeeds and balance decreases (bug). So we assert that balance is unchanged.
        assertEq(balanceAfter, balanceBefore, "Non-owner call must not drain contract balance");
    }
}

